1	import { describe, expect, it } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	type Cell = [number, number];
5	
6	const sorted = (cells: Cell[]): Cell[] =>
7	  [...cells].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
8	
9	describe("Game of Life nextGeneration", () => {
10	  it("returns an empty set of living cells for an empty input", () => {
11	    expect(nextGeneration([])).toEqual([]);
12	  });
13	  it("a single living cell at [0,0] dies of underpopulation -- []", () => {
14	    expect(nextGeneration([[0, 0]])).toEqual([]);
15	  });
16	  it("a living cell with exactly one living neighbour dies of underpopulation -- [[0,0],[1,0]] yields []", () => {
17	    expect(nextGeneration([[0, 0], [1, 0]])).toEqual([]);
18	  });
19	  it("a living cell with two living neighbours survives -- the centre [1,0] of the blinker [[0,0],[1,0],[2,0]] stays alive", () => {
20	    expect(nextGeneration([[0, 0], [1, 0], [2, 0]])).toContainEqual([1, 0]);
21	  });
22	  it("a living cell with three living neighbours survives -- the corner [0,0] of the block [[0,0],[1,0],[0,1],[1,1]] stays alive", () => {
23	    expect(nextGeneration([[0, 0], [1, 0], [0, 1], [1, 1]])).toContainEqual([0, 0]);
24	  });
25	  it("a living cell with more than three living neighbours dies of overpopulation -- the centre [1,1] of [[1,1],[0,1],[2,1],[1,0],[1,2]] is absent from the next generation", () => {
26	    expect(nextGeneration([[1, 1], [0, 1], [2, 1], [1, 0], [1, 2]])).not.toContainEqual([1, 1]);
27	  });
28	  it("a dead cell with exactly three living neighbours becomes alive by reproduction -- [[0,0],[1,0],[0,1]] yields [1,1] alive", () => {
29	    expect(nextGeneration([[0, 0], [1, 0], [0, 1]])).toContainEqual([1, 1]);
30	  });
31	  it("a dead cell with exactly two living neighbours stays dead -- [[0,0],[2,0]] yields no cell at [1,0]", () => {
32	    expect(nextGeneration([[0, 0], [2, 0]])).not.toContainEqual([1, 0]);
33	  });
34	  it("a dead cell with four living neighbours stays dead -- [[0,1],[2,1],[1,0],[1,2]] yields no cell at [1,1]", () => {
35	    expect(nextGeneration([[0, 1], [2, 1], [1, 0], [1, 2]])).not.toContainEqual([1, 1]);
36	  });
37	  it("only the eight surrounding cells count as neighbours -- a cell is not its own neighbour, so the pair [[0,0],[1,0]] dies instead of counting itself as a second neighbour", () => {
38	    expect(nextGeneration([[0, 0], [1, 0]])).not.toContainEqual([0, 0]);
39	  });
40	  it("the blinker oscillates -- horizontal [[0,0],[1,0],[2,0]] becomes vertical [[1,-1],[1,0],[1,1]]", () => {
41	    expect(sorted(nextGeneration([[0, 0], [1, 0], [2, 0]]))).toEqual(
42	      sorted([[1, -1], [1, 0], [1, 1]]),
43	    );
44	  });
45	  it("the block is still life -- [[0,0],[1,0],[0,1],[1,1]] is unchanged in the next generation", () => {
46	    expect(sorted(nextGeneration([[0, 0], [1, 0], [0, 1], [1, 1]]))).toEqual(
47	      sorted([[0, 0], [1, 0], [0, 1], [1, 1]]),
48	    );
49	  });
50	  it("handles negative coordinates -- the blinker at [[-1,-5],[0,-5],[1,-5]] becomes [[0,-6],[0,-5],[0,-4]]", () => {
51	    expect(sorted(nextGeneration([[-1, -5], [0, -5], [1, -5]]))).toEqual(
52	      sorted([[0, -6], [0, -5], [0, -4]]),
53	    );
54	  });
55	  it("the grid is unbounded -- a blinker at large coordinates [[1000000,1000000],[1000001,1000000],[1000002,1000000]] oscillates normally", () => {
56	    expect(
57	      sorted(nextGeneration([[1000000, 1000000], [1000001, 1000000], [1000002, 1000000]])),
58	    ).toEqual(sorted([[1000001, 999999], [1000001, 1000000], [1000001, 1000001]]));
59	  });
60	  it.todo("the result contains no duplicate cells");
61	  it.todo("the input array is not mutated");
62	  it.todo("the glider [[1,0],[2,1],[0,2],[1,2],[2,2]] becomes [[0,1],[2,1],[1,2],[2,2],[1,3]]");
63	});
